["Open the Floodgates"]={description="One of the Peacekeepers' Coalition's finest has challenged you to find the holy battlegrounds in the Rala Waterways. Head down and prove that you have what it takes to navigate the waters.",fame="Adoulin",fame_level="3",id=100,reward="1000 Experience Points\n500 Bayld",start_npc="Risen Hackles at Eastern Adoulin",start_pos="G-6"},
["Order Up"]={description="Visit the Twelve Orders and ascertain whether or not the information contained within the dossier that the library prepared on them is correct.",fame="Adoulin",id=30,reward="1000 Experience Points\n500 Bayld\nAbility to read the books in Celennia Memorial Library\nAbility to receive achievement rewards from Reja Ygridhi",start_npc="Reja Ygridhi",start_zone="Eastern Adoulin"},
["Orobon Appetit"]={description="A lone fisherman has his eyes on a rare delicacy--orobon meat. Fish 'em up, cut 'em up, and serve 'em up to satiate his hunger with the perfect cut of meat.",fame="Adoulin",id=59,reward="Paresis resilience\n500 Bayld",start_npc="Nestroh",start_pos="H-9",start_zone="Foret de Hennetiel"},
["Poisoning the Well"]={description="Researching the properties of the Zoldeff River may lead to insights that aid the colonization initiative. Collect some water from the mouth of the river and bring it back to Fritha.",fame="Adoulin",fame_level="1",id=10,repeatable="No",reward="2000 Experience Points\n200 Bayld",start_npc="Fritha",start_pos="J-7",start_zone="Foret de Hennetiel"},
["Quiescence"]={description="[This is a challenge] You smell of rotten-wotten rolanberries. Now come fightaru me.",fame="Adoulin",id=132,previous={"Destiny's Device"},reward="Epeolatry",start_npc="Gaddiux",start_zone="Western Adoulin"},
["Raptor Rapture"]={description="Vorahal, the Mummers' Coalition's most prized raptor, escaped his pen and evidently mauled a hapless citizen named Ilney. Go visit the victim and hear his side of the story.",fame="Adoulin",fame_level="1",id=73,next={"Vegetable Vegetable Crisis"},repeatable="No",reward="1000 Bayld",start_npc="Pagnelle",start_pos="G-10",start_zone="Western Adoulin"},
["Rune Fencing the Night Away"]={description="You have been given a great sword\n that, for reasons unbeknownst to you,\n has been outfitted with a device that\n measures durability. Moreover,\n something astonishing is supposed to\n occur when it is used a certain\n number of times.",fame="Adoulin",id=135,previous={"Children of the Rune"},requirements={{count=1,id=20749,name="Trial Blade"}},reward="300 Bayld\nAbility to use Dimidiation",start_npc="Gaddiux",start_zone="Western Adoulin"},
["Saved by the Bell"]={description="A fable recited by Nhili tells of a fearsome struggle that took place in the wilds many centuries past. Are the rumors true, and what do they have to do with the bell you found?",fame="Adoulin",id=131,previous={"The Communion"},reward="Idris",start_npc="Nhili Uvolep",start_pos="I-7",start_zone="Eastern Adoulin"},
["Scaredy-Cats"]={description="A couple of Pioneers' Coalition members have seen some fearsome sights in the forest, but their leader demands that they collect some soil samples there. Head to the Ceizak Battlegrounds and do their dirty work for them.",fame="Adoulin",fame_level="1",id=72,reward="Reive unity\n1000 Bayld",start_npc="Eamonn",start_pos="E-8",start_zone="Western Adoulin"},
["Sick and Tired"]={description="An epidemic possibly originating in\n the Great Expedition has gripped\n Adoulin with fear. Meet up with\n Alianne at Yorcia Weald's frontier\n station to apprise her of the\n situation.",fame="Adoulin",id=133,next={"Not-So-Clean Bill"},previous={"Hypocritical Oath"},reward="1,000 Bayld",start_npc="Svenja",start_pos="I-8",start_zone="Western Adoulin"},
["Talk About Wrinkly Skin"]={description="A strange old man has taken a liking to the hot springs found in Morimar, which has Orsa-Porsa rather nonplussed. The Taru has tasked you with bringing him some Uleguerand milk, an apkallu egg, and a felicifruit so he can lure the old man out of hiding.",fame="Adoulin",id=60,requirements={{count=1,id=5568,name="Apkallu Egg"},{count=1,id=5964,name="Felicifruit"},{count=1,id=5703,name="Uleguerand Milk"}},reward="[Key Item]Calor resilience\n500 bayld",start_npc="Orsa-Porsa",start_pos="K-10",start_zone="Morimar Basalt Fields"},
["The Bloodline of Zacariah"]={description="Preparations for Hostenn's funeral are ongoing, and Sylvie wishes to commence a ritual for him. Collect three chunks of acuex ore, which can be found on acuexes in Cirdas Caverns.",fame="Seekers of Adoulin",id=37,next={"The Communion"},previous={"For Whom the Bell Tolls"},repeatable="No",requirements={{count=3,id=4042,name="Acuex Ore"}},reward="Geomancy Mitaines",start_npc="Sylvie",start_pos="I-5",start_zone="Western Adoulin"},
["The Communion"]={description="Lhaiso Neftereh has fallen ill, perhaps because of the anomalies in the earth. Sylvie wants you to accompany her to the Order of Renaye residence in Eastern Adoulin to check up on Lhaiso.",fame="Seekers of Adoulin",id=38,next={"Geomancer Relic Armor","Saved by the Bell"},previous={"The Bloodline of Zacariah"},repeatable="No",requirements={{count=1,id=2375,ki=true,name="[Key Item] Lhaiso Neftereh's bell"}},reward="Geomancy Pants \nUp to 10,000 Bayld",start_npc="Sylvie",start_pos="I-5",start_zone="Western Adoulin",title="Storied Geomancer"},
["The Curious Case of Melvien"]={description="Margret postulated that Melvien's death was by human hands. Aid her in finding the truth.",fame="Adoulin",fame_level="7",id=138,next={"A Thirst Before Time"},reward="4k Experience Points, 1,250 Bayld\n5 Pinches of High-Purity Bayld",start_npc="Estelle",start_pos="F-9",start_zone="Eastern Adoulin"},
["The Good, the Bad, the Clement"]={description="Nashu has gone to return the catalyst the Blackthorn Coven gave him and convince the trio to end their involvement with the Velkk. Accompany him to the showdown in Yorcia Weald.",fame="Seekers of Adoulin",id=125,next={"The Weatherspoon Inquisition"},previous={"Velkkovert Operations"},repeatable="No",reward="500 EXP, 1,000 Bayld",start_npc="Zaffeld",start_pos="J-8",start_zone="Eastern Adoulin"},
["The Longest Way Round..."]={description="Making the rounds is too tough for a certain soldier...but not for you! Make sure the area is safe and report back.",fame="Adoulin",fame_level="1",id=91,reward="1000 Experience Points\n500 Bayld",start_npc="Vastran",start_pos="F-8",start_zone="Eastern Adoulin"},
["The Old Man and the Harpoon"]={description="A lone fisherman will lose his battle with the big one unless you carry his trusty harpoon to the Inventors' Coalition for repair.",fame="Adoulin",fame_level="1",id=77,next={"Fertile Ground"},repeatable="No",reward="500 Experience Points\n300 Bayld",start_npc="Jorin",start_pos="J-4",start_zone="Western Adoulin"},
["The Secret to Success"]={description="Erfimia is convinced that there is no way a run-of-the-mill exorcist like Robertioux could pull off such an incredible feat without a clandestine training regime, and thus wants you to discover his secret.",fame="Adoulin",fame_level="3",id=127,next={"Eye of the Beholder"},reward="1000 Bayld",start_npc="Behsa Alehgo",start_pos="J-8",start_zone="Eastern Adoulin"},
["The Silent Forest"]={description="Living in harmony with the forest requires the assistance of the avatar Siren. Head to Escha - Ru'Aun and look for clues regarding her disappearance.",fame="Adoulin",id=144,next={"Winds of Eternity"},previous={"The Light Within","A Rhapsody for the Ages"},reward="Choice of one:\nPact with Siren\n10,000 Bayld",start_npc="Levil",start_pos="E-8",start_zone="Western Adoulin",title="Eternal Communer"},
["The Starving"]={description="Everyone's favorite famished Galka once again hungers for the delicacies of the Middle Lands. This time however, he wants a certain drink that packs a punch in more ways than one.",fame="Adoulin",fame_level="2",id=84,next={"\"Always more,\" Quoth the Ravenous"},previous={"Hunger Strikes"},repeatable="No",reward="1000 Experience Points\n500 Bayld",start_npc="Westerly Breeze",start_pos="I-5",start_zone="Western Adoulin",title="None"},
["The Weatherspoon Inquisition"]={description="Under the orders of Vortimere, Araustoix has led a contingent of exorcists on a witch hunt of the most literal kind. Head to Yorcia Weald with Nashu to warn the enigmatic Blackthorn Coven.",fame="Seekers of Adoulin",id=136,next={"The Weatherspoon War"},previous={"The Good, the Bad, the Clement"},reward="500 EXP\n1,000 Bayld",start_npc="Nashu",start_zone="Eastern Adoulin"},
["The Weatherspoon War"]={description="The Velkk, Mligni-Vorgut, has seized an artifact with the power to destroy Adoulin. The exorcists want you to help stop him at the Seat of Gramk-Droog.",fame="Adoulin",id=141,previous={"The Weatherspoon Inquisition"},reward="1,000 Experience Points\n1,000 Bayld",start_npc="Nashu",start_zone="Marjami Ravine",title="Protector of the Sacred City"},
["The Whole Place Is Abuzz"]={description="Numbing blossoms have antidotal effects that inhibit the poisons of pungent fungi. Head to the dead end to the southwest and use the Land of Milk and Honey beehive to collect ten bees. Make sure you are resting quietly to collect them!",fame="Adoulin",id=58,reward="[Key Item]Toxin resilience\n500 Bayld",start_npc="Rumin-Flumin",start_pos="H-9",start_zone="Yahse Hunting Grounds"},
["Thorn in the Side"]={description="The Blackthorn Coven has been causing inordinate amounts of trouble for Adoulin with the traps they are setting. Trek to J-6 in Yorcia Weald to capture these mavens of mischief and set the sacred city at ease.",fame="Adoulin",fame_level="3",id=121,next={"Velkkovert Operations"},repeatable="No",reward="1,000 Bayld",start_npc="Zaffeld",start_pos="J-8",start_zone="Eastern Adoulin"},
["To Catch a Predator"]={description="One of the local mantids has been terrorizing the area. Use some of the chapuli around the bivouac as bait to lure it out of hiding and exterminate the threat.",fame="Adoulin",id=1,reward="2000 Experience Points\n200 Bayld",start_npc="Lucretia",start_pos="H-9",start_zone="Ceizak Battlegrounds"},
["To Laugh Is to Love"]={description="Tuffle-Buffle requests your input to help Musto-Rusto win over his love, Minnifi.",fame="Adoulin",fame_level="3",id=104,next={"A Barrel of Laughs"},previous={"All the Way to the Bank"},reward="1000 Experience Points",start_npc="Peladi Shalmohr",start_pos="G-10",start_zone="Western Adoulin Mummers' Coalition",title="The Lovelorn"},
["Transporting"]={description="A mysterious package has been accidentally delivered to the wrong address. Take it with you to the warehouse on the Adoulin Waterfront so that it can be hauled to its proper recipient.",fame="Adoulin",fame_level="2",id=82,repeatable="No",reward="1000 Experience Points\n300 Bayld",start_npc="Vaulois",start_pos="H-6",start_zone="Western Adoulin"},
["Treasures of the Earth"]={description="Sylvie still has lingering doubts about her father. Meet up with her in Morimar Basalt Fields for moral support.",fame="Adoulin",id=142,previous={"Geomancer Relic Armor"},repeatable="Yes",requirements={{count=1,id=2388,ki=true,name="[Key Item] \"Climbing\""},{count=1,id=2795,ki=true,name="[Key Item] Holla crystal of gales"},{count=1,id=2796,ki=true,name="[Key Item] Dem crystal of dunes"},{count=1,id=2797,ki=true,name="[Key Item] Mea crystal of flames"},{count=1,id=2798,ki=true,name="[Key Item] Pale azure cloth"},{count=1,id=2794,ki=true,name="[Key Item] Treatise on azimuth clothcraft"}},reward="Azimuth Coat \n15,000 Experience Points\n10,000 Bayld (109 Fight) or\n3 Synthesis Materials (125 Fight) or\n10 Synthesis Mats and a Codex of Etchings (135 Fight)",start_npc="Sylvie",start_pos="I-5",start_zone="Western Adoulin",title="Lifecycler (Level 135 fight only)"},
["Twitherym Dust"]={description="The southern section of the battlegrounds is home to a lek of twitherym, and the dust on their wings is said to have magical properties. Collect some sap exuding from the trees there and report back to Gurren-Murren.",fame="Adoulin",fame_level="1",id=0,repeatable="No",reward="1000 Experience Points\n100 Bayld",start_npc="Gurren-Murren",start_pos="K-7",start_zone="Ceizak Battlegrounds",title="None"},
["Unsullied Lands"]={description="Not all ground near the Zoldeff River has succumbed to corruption--an ergon locus located nearby is keeping the surrounding lands pristine. If you run across the locus, collect a sample of the surrounding sand.",fame="Adoulin",fame_level="1",id=12,reward="2000 Experience Points\n200 Bayld",start_npc="Inmot-Pinmot",start_pos="J-10",start_zone="Foret de Hennetiel"},
["Vegetable Vegetable Crisis"]={description="Amchuchu asks you deliver a missive\n to Cid proclaiming that Junior's plan\n fell through--but first, she wants you\n to bring back a midrium ingot, some\n urunday lumber, and a square of\n raaz leather.",fame="Adoulin",id=110,next={"Vegetable Vegetable Frustration"},previous={"Vegetable Vegetable Evolution","Raptor Rapture"},reward="12 Rarab Tail, 2000 bayld",start_npc="Amchuchu (Inventors' Coalition",start_zone="Western Adoulin)",title="Inventor Extraordinaire"},
["Vegetable Vegetable Evolution"]={description="Midras has headed off to Yorcia Weald for further research into potential fertilizer ingredients, and Amchuchu is worried sick about him. Venture into the forest and ensure that he is safe.",fame="Adoulin",fame_level="4",id=109,next={"Vegetable Vegetable Crisis"},previous={"Vegetable Vegetable Revolution"},reward="2,000 Bayld and 12 Rarab Tails",start_npc="Door: Amuchuchu's Laboratory",start_zone="Western Adoulin",title="Vegetable Evolutionary"},
["Vegetable Vegetable Frustration"]={description="Hoping to lift Midras out of his melancholic state, Amchuchu has sent you to Bastok to find out what first inspired him to become an inventor.",fame="Adoulin",id=111,previous={"Vegetable Vegetable Crisis","The Usual"},requirements={{count=1,id=17399,name="Sabiki Rig"}},reward="2,000 Bayld",start_npc="Amchuchu (Inventors' Coalition",start_zone="Western Adoulin)",title="Vegetable Hero"},
["Vegetable Vegetable Revolution"]={description="The recent population explosion in Adoulin has been causing food problems. Seek out Midras to assist him and Amchuchu in finding a new mineral ore in the Sih Gates so they can fabricate improved fertilizer.",fame="Adoulin",fame_level="1",id=108,next={"Vegetable Vegetable Evolution"},repeatable="No",reward="12 Rarab Tail\n2000 Bayld",start_npc="Door: Amuchuchu's Laboratory",start_pos="J-10",start_zone="Western Adoulin",title="Vegetable Revolutionary"},
["Velkkovert Operations"]={description="The Blackthorn Coven has been conspiring with the Velkk, but to what end? Get to the bottom of this bewitching development before it is too late.",fame="Adoulin",id=123,next={"The Good, the Bad, the Clement"},previous={"Thorn in the Side"},repeatable="No",reward="500 EXP, 1,000 Bayld",start_npc="Zaffeld",start_pos="J-8",start_zone="Eastern Adoulin"},
["Water, Water, Everywhere"]={description="Velkk encampments are impeding progress into surveys of the river in Marjami Ravine. Collect samples from the upper and lower sections, as well as from water near the Dho Gates.",fame="Seekers of Adoulin",fame_level="4+",id=32,reward="2000 Experience Points\n1000 Bayld",start_npc="Jhen Durheka",start_zone="Marjami Ravine"},
["Wayward Waypoints"]={description="The curmudgeon Sharuru is concerned about the health of her waypoint friends located far outside of Adoulin proper. Help her recalibrate the waypoints in Jeuno and at the various frontier stations.",fame="Adoulin",fame_level="4",id=27,previous={"Meg-alomaniac"},reward="1000 Experience Points\n500 Bayld\n3000 Kinetic Units",start_npc="Sharuru",start_zone="Eastern Adoulin"},
["Wes...Eastern Waypoints, Ho!"]={description="Attune your geomagnetron to each of the waypoints in Eastern Adoulin and report back.",fame="Adoulin",fame_level="1",id=51,next={"Meg-alomaniac"},reward="1000 Experience Points\n500 Bayld\n3000 Kinetic Units",start_npc="Sharuru",start_pos="F-8",start_zone="Eastern Adoulin"},
["Western Waypoints, Ho!"]={description="Attune your geomagnetron to each of the waypoints in Western Adoulin and report back.",fame="Adoulin",fame_level="1",id=50,reward="1000 Experience Points\n500 Bayld\n3000 Kinetic Units",start_npc="Alienor",start_pos="E-8",start_zone="Western Adoulin"},
["Winds of Eternity"]={description="Gather ergon power and revisit a familiar land in order to confirm your bond with Siren.",fame="Adoulin",id=145,previous={"The Silent Forest"},repeatable="Yes",reward="Choice of one:\n: Pact with Siren\n:* 10,000 Bayld",start_npc="Siren",start_pos="H-7",start_zone="Leafallia",title="Eternal Communer"},
}
